package rlvm.spike.stepper;

import static rlvm.spike.stepper.Terms.*;
import static rlvm.spike.stepper.Vals.*;

/**
 * (R) Plain host recursion: the baseline and the specification of the four judgments. With INERT set (variant
 * Ri, generated by scripts/build.sh) constant-headed application nests go through {@link Inert#eval}, the same
 * scratch-buffer loop the worklist variant W1 uses.
 */
public final class Rec extends Engine {
    static final boolean INERT = false;

    static int eval(int e, int env) {
        if (STATS) {
            Stat.evals++;
            Stat.check();
        }
        switch (kind[e]) {
            case BVAR:
                return lookup(env, ea[e]);
            case SORT:
                return mk2(K_SORT, ea[e]);
            case CONST:
                return mk2(K_CONST, ea[e]);
            case LIT:
                return mk2(K_LIT, e);
            case APP: {
                if (INERT && (flag[e] & Terms.INERT) != 0) {
                    return Inert.eval(e, env);
                }
                int f = eval(ea[e], env);
                int x = eval(eb[e], env);
                if (f > 0 && H[f] == K_LAM) {
                    return eval(eb[H[f + 1]], mk3(K_ENV, H[f + 2], x));
                }
                return mk3(K_APP, f, x);
            }
            case LAM:
                return mk3(K_LAM, e, env);
            case PI:
                return mk3(K_PI, e, env);
            case LET: {
                int v = eval(eb[e], env);
                return eval(ec[e], mk3(K_ENV, env, v));
            }
            case PROJ:
                if (INERT && (flag[e] & Terms.INERT) != 0) {
                    return Inert.eval(e, env);
                }
                return mk2(K_PROJ | eb[e] << 4, eval(ec[e], env));
            default:
                throw new IllegalStateException();
        }
    }

    static int readback(int v, int depth) {
        if (STATS) {
            Stat.rbs++;
        }
        if (v < 0) {
            return mk(BVAR, depth + v, 0, 0); // index = depth - 1 - level, level = -v - 1
        }
        int hdr = H[v];
        switch (hdr & 15) {
            case K_APP: {
                int tf = readback(H[v + 1], depth);
                int ta = readback(H[v + 2], depth);
                return mk(APP, tf, ta, 0);
            }
            case K_PROJ:
                return mk(PROJ, 0, hdr >>> 4, readback(H[v + 1], depth));
            case K_LAM, K_PI: {
                int e = H[v + 1], env = H[v + 2];
                int td = readback(eval(ea[e], env), depth);
                int tb = readback(eval(eb[e], mk3(K_ENV, env, -(depth + 1))), depth + 1);
                return mk((hdr & 15) == K_LAM ? LAM : PI, td, tb, 0);
            }
            case K_SORT:
                return mk(SORT, H[v + 1], 0, 0);
            case K_CONST:
                return mk(CONST, H[v + 1], 0, 0);
            case K_LIT:
                return H[v + 1];
            default:
                throw new IllegalStateException();
        }
    }

    static boolean conv(int a, int b, int depth) {
        if (STATS) {
            Stat.convs++;
        }
        if (a == b) {
            return true;
        }
        if (a < 0 || b < 0) {
            return false;
        }
        int hdr = H[a];
        if (hdr != H[b]) {
            return false;
        }
        switch (hdr & 15) {
            case K_APP:
                return conv(H[a + 1], H[b + 1], depth) && conv(H[a + 2], H[b + 2], depth);
            case K_PROJ:
                return conv(H[a + 1], H[b + 1], depth);
            case K_LAM, K_PI: {
                int ta = H[a + 1], enva = H[a + 2], tb = H[b + 1], envb = H[b + 2];
                int da = eval(ea[ta], enva);
                int db = eval(ea[tb], envb);
                if (!conv(da, db, depth)) {
                    return false;
                }
                int x = -(depth + 1);
                int va = eval(eb[ta], mk3(K_ENV, enva, x));
                int vb = eval(eb[tb], mk3(K_ENV, envb, x));
                return conv(va, vb, depth + 1);
            }
            default:
                return false; // SORT, CONST, LIT: hash-consed, so different ids are different values
        }
    }

    @Override
    public void decl(int root) {
        int v = eval(root, 0);
        int t = readback(v, 0);
        int u = eval(t, 0);
        nf = t;
        w = u;
        ok = conv(v, u, 0);
    }
}
